{{ (function(){
var d=(getTk.data&&getTk.data[0])||{};
var CSS="@page{size:A4;margin:14mm 15mm 12mm}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#f3f4f6}body{font-family:Helvetica,Arial,sans-serif;color:#111827;font-size:10.5pt;line-height:1.45}.sivu{background:#fff;max-width:210mm;margin:0 auto 24px;padding:14mm 15mm 12mm}.tyokalut{position:sticky;top:0;z-index:5;text-align:center;padding:10px 0;background:#f3f4f6;border-bottom:1px solid #e5e7eb}.tyokalut button{font:inherit;font-weight:700;padding:9px 22px;border:0;border-radius:6px;background:#B91C1C;color:#fff;cursor:pointer}header{text-align:center;border-bottom:2px solid #B91C1C;padding-bottom:5mm;margin-bottom:6mm}header img{height:15mm;width:auto}h1{font-size:14pt;letter-spacing:.18em;text-transform:uppercase;margin:4mm 0 1mm;color:#B91C1C;font-weight:700}.tp{font-size:13pt;font-weight:700}h2{font-size:8.5pt;letter-spacing:.14em;text-transform:uppercase;color:#B91C1C;border-bottom:1px solid #e5e7eb;padding-bottom:1.5mm;margin:7mm 0 3.5mm;font-weight:700}section:first-of-type h2{margin-top:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:3.5mm 10mm}.otsikko{font-size:7.5pt;letter-spacing:.08em;text-transform:uppercase;color:#6b7280;margin-bottom:.6mm}.arvo{font-size:11pt}.tyhja{color:#9ca3af}.teksti{border:1px solid #e5e7eb;border-radius:1.5mm;padding:3mm 3.5mm;min-height:20mm}.teksti p{margin:0 0 2mm}.teksti p:last-child{margin-bottom:0}.pieni{font-size:9.5pt;min-height:14mm}table.tunnit{width:100%;border-collapse:collapse;margin-top:1mm}table.tunnit th{font-size:7.5pt;letter-spacing:.08em;text-transform:uppercase;color:#6b7280;text-align:left;font-weight:600;padding-bottom:1.5mm}table.tunnit td{border-bottom:1px solid #9ca3af;height:9mm}tr.summa td{border-bottom:2px solid #111827;font-size:9pt;color:#374151;padding-top:2mm}.allekirjoitus{margin-top:9mm}.viiva{border-bottom:1px solid #9ca3af;height:9mm;max-width:95mm}footer{margin-top:9mm;border-top:1px solid #e5e7eb;padding-top:2mm;font-size:8pt;color:#6b7280;display:flex;justify-content:space-between}@media print{.tyokalut{display:none} html,body{background:#fff} .sivu{max-width:none;margin:0;padding:0} }";
var LOGO="data:image/webp;base64,";
var e=function(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
var tyhja='<span class="tyhja">&mdash;</span>';
var v=function(s){var t=(s==null)?'':String(s).trim();return t===''?tyhja:e(t);};
var pv=function(s){return s?moment(s).format('D.M.YYYY'):tyhja;};
var eur=function(n){return (n==null||n==='')?tyhja:Number(n).toFixed(2).replace('.',',')+' &euro;';};
var kyllaEi=function(b){return b===true?'Kyll&auml;':(b===false?'Ei':tyhja);};
var k=function(o,a){return '<div><div class="otsikko">'+o+'</div><div class="arvo">'+a+'</div></div>';};
var rikas=function(h){var s=String(h==null?'':h).trim();return (s===''||s==='<p><br></p>')?('<p class="tyhja">&mdash;</p>'):s;};
var rivi='<tr><td></td><td></td><td></td></tr>';
return '<!doctype html><html lang="fi"><head><meta charset="utf-8"><title>Ty&ouml;kortti '+e(d.tp_numero)+'</title><style>'+CSS+'</style></head><body>'
+'<div class="tyokalut"><button type="button" onclick="window.print()">Tulosta / Tallenna PDF</button></div>'
+'<div class="sivu">'
+'<header><img src="'+LOGO+'" alt="Kilpipaino"><h1>Ty&ouml;kortti</h1><div class="tp">'+v(d.tp_numero)+'</div></header>'
+'<section><h2>Perustiedot</h2><div class="grid">'
+k('Saapunut',pv(d.created_at))
+k('Tila',v(statusSelect.selectedOptionLabel))
+k('Asiakas',v(d.asiakas_nimi))
+k('Yritys',v(d.asiakas_yritys))
+k('S&auml;hk&ouml;posti',v(d.asiakas_email))
+k('Vastuuhenkil&ouml;',v(d.omistaja))
+'</div></section>'
+'<section><h2>Tilaustiedot</h2><div class="grid">'
+k('Valmistumisp&auml;iv&auml;',pv(d.valmistumispaiva))
+k('Suunniteltu asennusp&auml;iv&auml;',pv(d.asennuspaiva))
+k('Ty&ouml;h&ouml;n sis&auml;ltyy asennus',kyllaEi(d.asennus_sisaltyy))
+k('Laskutusperuste',v(Select1.selectedOptionLabel))
+k('Hinta (alv 0 %)',eur(d.hinta_yhteensa))
+k('Asiakkaan viite',v(d.asiakkaan_viite))
+k('Suunnitellut ty&ouml;tunnit',v(d.suunnitellut_tunnit))
+'</div></section>'
+'<section><h2>Ty&ouml;n kuvaus ja ty&ouml;ohjeet</h2><div class="teksti">'+rikas(d.tyon_kuvaus)+'</div></section>'
+'<section><h2>Sis&auml;iset lis&auml;tiedot</h2><div class="teksti pieni">'+rikas(d.tilaus_lisatiedot)+'</div></section>'
+'<section><h2>Toteutuneet ty&ouml;tunnit</h2><table class="tunnit"><thead><tr><th style="width:26%">P&auml;iv&auml;m&auml;&auml;r&auml;</th><th style="width:44%">Tekij&auml;</th><th style="width:30%">Tunnit</th></tr></thead><tbody>'+rivi+rivi+rivi+rivi+'<tr class="summa"><td colspan="2">Yhteens&auml;</td><td></td></tr></tbody></table>'
+'<div class="allekirjoitus"><div class="viiva"></div><div class="otsikko">P&auml;iv&auml;ys ja allekirjoitus</div></div></section>'
+'<footer><span>Nokian Kilpipaino Oy</span><span>'+v(d.tp_numero)+'</span><span>Tulostettu '+moment().format('D.M.YYYY')+'</span></footer>'
+'</div></body></html>';
})() }}
